import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"59、【涣】 坎下巽上","description":"周易口诀义 - 59、【涣】 坎下巽上","frontmatter":{"title":"59、【涣】 坎下巽上","description":"周易口诀义 - 59、【涣】 坎下巽上"},"headers":[],"relativePath":"zh/classics/koujueyi/061.md","filePath":"zh/classics/koujueyi/061.md"}'),r={name:"zh/classics/koujueyi/061.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_59、【涣】-坎下巽上" tabindex="-1">59、【涣】 坎下巽上 <a class="header-anchor" href="#_59、【涣】-坎下巽上" aria-label="Permalink to “59、【涣】 坎下巽上”">​</a></h1><p>彖曰：「涣亨」，刚来而不穷，柔得位乎外而上同。「王假有庙」，王乃在中也。「利涉大川」，乘木有功也。</p><p>象曰：风行水上，「涣」。先王以享于帝，立庙。</p><p>初六：用拯马壮，吉。</p><p>象曰：初六之吉，顺也。</p><p>九二，涣奔其机，悔亡。</p><p>象曰：「涣奔其机」，得愿也。</p><p>六三，涣其躬，无悔。</p><p>象曰：「涣其躬」，志在外也。</p><p>六四，涣其群，元吉。涣有丘，匪夷所思。</p><p>象曰：「涣其群元吉」，光大也。</p><p>九五，涣汗其大号。涣，王居无咎。</p><p>象曰：「王居无咎」，正位也。</p><p>上九，涣其血，去逖出，无咎。</p><p>象曰：「涣其血」，远害也。</p><p>解读</p><p>「涣亨，王假有庙」者，涣者，离散之名，缓释为义。然则小人遭难，奔走逃散，逃散方始获济。大德之人，处难之时，能建功立德，散释险难，以安时人，故谓之「涣」也。能释险难，人皆获济，所以亨通。王能释难而通，天下太平，至于建立宗庙，德洽人神，虽复大川，亦可济涉。险难既释，宜弘道化，利物聚人，莫过于正，故曰「利涉大川，利贞」也。象曰「风行水上，涣」者，风行水上，激扬波涛，散释之象。「先王以享于帝，立庙」者，先王既释险难，民泰时安，可以享献上帝，建立宗庙，祭祀祖考，告以太平也。</p><p>「初六，用拯马壮，吉」者，拯，拔也；初六处难之初，乖散未甚，可以用马拯拔，得其志而远难，难初未至危剧，相时而行，是壮而获吉也。</p><p>「九二，涣奔其机，悔亡」者，机是案机以承物也，谓初与二俱无应相得，既托于初，得其所安，逃难离散而奔，故曰「涣奔其机，悔亡」也。</p><p>「六三，涣其躬，无咎」者，涣之为义，内险外安，六三有应于外，不顾所守，脱身而出，与刚合志，故得悔亡，故曰「涣其躬，无悔」也。</p><p>「六四，涣其群，元吉，涣有丘，匪夷所思」者，六四既在险外，即是已险难之人，近于至尊，为君委任，内主枢密，外宣王命，而能散群众之难，以安绥万人也，而获其大功，所以「元吉」，故「涣其群，元吉」。然为君所任，任重忧深，虽能散众之难，犹疑散难之中，恐有未平丘墟之险，恒怀思虑，心未得安，故曰「涣有丘，匪夷所思」也。丘，丘墟也；夷，平也。</p><p>「九五，涣汗其大号，涣王居无咎」者，人之惊怖既汗从体流，故以训释为「汗」也。九五处于尊位而能发号施令，大散天下之险危，故曰「涣汗其大号」也。为涣之主，能散险难，若非王者正位则不能，然正位不可假人，故王居无咎也。</p><p>「上九：涣其血，去逖出，无咎」者，血，伤害之义；逖，远也。上九所居最是险外，是不为物之侵伤，逖远而去，拔出险外，故曰「涣其血」也。散患于远害之地，谁能与我为咎也？</p>',23)])])}const u=e(r,[["render",i]]);export{h as __pageData,u as default};
